default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\System' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('EnableSmartScreen', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]1)) {
    Write-Output 'Mismatch: HKLM:\Software\Policies\Microsoft\Windows\System [EnableSmartScreen]'
    $mismatchCount++
}

$key = Get-Item -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\System' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('ShellSmartScreenLevel', $null, 'DoNotExpandEnvironmentNames') }
$kind = $null
if ($null -ne $current) { $kind = $key.GetValueKind('ShellSmartScreenLevel') }
if (-not ($current -is [string] -and $kind -ceq 'String' -and $current -ceq 'Block')) {
    Write-Output 'Mismatch: HKLM:\Software\Policies\Microsoft\Windows\System [ShellSmartScreenLevel]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\System')) {
    New-Item -Path 'HKLM:\Software\Policies\Microsoft\Windows\System' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\System' -Name 'EnableSmartScreen' -Value 1 -PropertyType DWord -Force | Out-Null
if (-not (Test-Path -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\System')) {
    New-Item -Path 'HKLM:\Software\Policies\Microsoft\Windows\System' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\System' -Name 'ShellSmartScreenLevel' -Value 'Block' -PropertyType String -Force | Out-Null
exit 0
